UPDATE products SET description='اجعلي للعناية وقتًا مريحًا بين تفاصيل يومكِ. زبدة الجسم المخفوقة بالعنب من سادور تحوّل الترطيب إلى طقس تستمتعين به. خذي كمية صغيرة ووزعيها على المناطق الجافة بعد الاستحمام، لتدللي بشرتكِ بملمس أكثر نعومة ولمسة عناية تستحقينها.',details_json=json_set(details_json,'$.tagline','لأن وقت العناية، وقت لكِ.','$.en.tagline','A little care in the quieter moments.','$.en.description','Make a little comfortable space for care in your everyday routine. SADOER · Grape Whipped Body Butter Cream. Little moments of care, just for you. Choose a small moment of beauty that fits the way you like to get ready.','$.toneVersion','4.1.0'),updated_at=datetime('now') WHERE id='TS0326' AND description='دلال يومي لكل تفاصيلكِ. زبدة الجسم المخفوقة بالعنب من سادور تحوّل الترطيب إلى طقس تستمتعين به. خذي كمية صغيرة ووزعيها على المناطق الجافة بعد الاستحمام، لتدللي بشرتكِ بملمس أكثر نعومة ولمسة عناية تستحقينها.' AND COALESCE(json_extract(details_json,'$.tagline'),'')='ملمس مخفوق، ولحظة حلوة لجسمكِ.';
